# Every refusal_reason chat has logged for a provider failure. Matched exactly:
# a refusal's reason is otherwise the gate's free text, which could end in
# "unavailable" without being an outage.
OUTAGE_REASONS = ("generation unavailable", "retrieval unavailable", "condense unavailable")


def mark_past_outages(apps, schema_editor):
    """Rows logged before the column existed said they were outages only in
    refusal_reason; left False, the dashboard would count them as refusals."""
